export type Post = {
  id: number;
  title: string;
  body: string;
};

const posts: Post[] = [];
let nextId = 1;

export function getPosts(): Post[] {
  return posts;
}

export function addPost(title: string, body: string): Post {
  const post: Post = { id: nextId++, title, body };
  posts.push(post);
  return post;
}

